<?php
session_start();require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/legacy_activation.php';require_once __DIR__.'/../includes/legacy_ui.php';
requireRole(['admin','kasir']);
if(unit_all_readonly()){http_response_code(409);exit('Pilih SD, SMP, atau SMA di sidebar untuk aktivasi siswa Legacy.');}
if(empty($_SESSION['csrf_legacy_activation']))$_SESSION['csrf_legacy_activation']=bin2hex(random_bytes(32));
$legacyStudentId=filter_var($_POST['id']??$_GET['id']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$error='';
if($legacyStudentId===false){http_response_code(400);exit('Identitas siswa tidak valid. Buka kembali dari Data Siswa.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_legacy_activation'],$_POST['csrf_token'])){http_response_code(403);exit('Token CSRF tidak valid.');}
    try{
        if(isset($_GET['id'])&&(string)$_GET['id']!==(string)$legacyStudentId){$urlId=filter_var($_GET['id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($urlId!==false)$legacyStudentId=$urlId;throw new RuntimeException('Formulir aktivasi kedaluwarsa. Periksa kembali siswa dan isian sebelum mengirim ulang.');}
        if(($_POST['action']??'')!=='preview'){
            if(array_key_exists('pangkal',$_POST))throw new RuntimeException('Formulir aktivasi kedaluwarsa; muat ulang halaman.');
            if(($_POST['confirmed']??'')!=='1')throw new RuntimeException('Konfirmasikan tahun, kelas, dan tarif operasional.');
            legacy_activate($koneksi,$legacyStudentId,(int)($_POST['class_id']??0),(int)($_POST['year_id']??0),array_intersect_key($_POST,array_flip(['spp','psb','komite','du'])),(int)$_SESSION['admin_id'],(string)$_SESSION['admin_nama']);header('Location: daftar.php');exit;
        }
    }catch(Throwable $e){http_response_code(409);$error=$e instanceof mysqli_sql_exception?'Aktivasi dibatalkan; periksa status dan relasi siswa.':$e->getMessage();}
}elseif($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit;}
$s=$koneksi->prepare('SELECT s.*,m.source_class,m.source_name,m.raw_data FROM siswa s JOIN legacy_student_import m ON m.student_id=s.id WHERE s.id=?');$s->bind_param('i',$legacyStudentId);$s->execute();$student=$s->get_result()->fetch_assoc();$s->close();if(!$student){http_response_code(404);exit('Siswa Legacy tidak ditemukan pada unit ini.');}
$classes=class_all($koneksi,true,false);$years=$koneksi->query("SELECT id,label,status FROM tahun_ajaran WHERE status IN ('published','draft') ORDER BY label='".du_current_academic_year()."' DESC,status='published' DESC,label DESC")->fetch_all(MYSQLI_ASSOC);
$rates=[];foreach($years as $year)foreach($classes as $class)$rates[$year['id']][$class['id']]=spp_current_effective_rate($koneksi,(string)$class['tingkat'],0,$year['label']);
function la_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$sourceRaw=json_decode($student['raw_data'],true)?:[];$sourceKomite=null;
try{$sourceKomite=legacy_source_komite($sourceRaw);}catch(DomainException $e){$sourceKomite=null;}
$activationValues=['spp'=>'0','psb'=>'0','komite'=>$sourceKomite??'','du'=>'0'];
if($_SERVER['REQUEST_METHOD']==='POST')foreach($activationValues as $key=>$value)if(isset($_POST[$key])&&is_string($_POST[$key]))$activationValues[$key]=$_POST[$key];
$selectedClass=(int)($_POST['class_id']??0);$selectedYear=(int)($_POST['year_id']??($years[0]['id']??0));
$selectedRate=$rates[$selectedYear][$selectedClass]??null;
if(($_POST['action']??'')==='preview'&&$selectedRate)$activationValues['spp']=(string)$selectedRate['net'];
?><!doctype html><html lang="id" data-palette="<?= unit_palette_for_view() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aktivasi Legacy | SistemSPP</title><link rel="stylesheet" href="../assets/css/style.css?v=<?= filemtime(__DIR__.'/../assets/css/style.css') ?>"><link rel="stylesheet" href="../assets/css/backup_restore.css?v=<?= filemtime(__DIR__.'/../assets/css/backup_restore.css') ?>"><link rel="stylesheet" href="../assets/css/date_controls.css?v=<?= filemtime(__DIR__.'/../assets/css/date_controls.css') ?>"><script>(function(){document.documentElement.setAttribute('data-theme',localStorage.getItem('spp_theme')||'light');})();</script><link rel="stylesheet" href="../assets/css/legacy_ui.css?v=<?= filemtime(__DIR__.'/../assets/css/legacy_ui.css') ?>"><link rel="stylesheet" href="../assets/css/legacy_workspace.css?v=<?= filemtime(__DIR__.'/../assets/css/legacy_workspace.css') ?>"></head><body><div class="layout">
<?php legacy_ui_sidebar(); ?><main class="main-content dbt-main"><?php legacy_ui_topbar('Aktifkan & Tempatkan','Data Siswa / Legacy'); ?><div class="db-tools-page legacy-ui legacy-activation-workspace"><header class="dbt-heading"><div><span class="legacy-eyebrow">DATA SISWA LEGACY</span><h1>Aktifkan &amp; tempatkan siswa</h1><p>Pilih kelas dan tahun ajaran, lalu periksa tarif sebelum menyimpan.</p></div><a class="dbt-button dbt-button-outline" href="daftar.php?status=legacy"><?= legacy_ui_icon('back') ?> Kembali ke Data Siswa</a></header><section class="dbt-card"><h2><?= la_e($student['NAMA']) ?> · <?= la_e($student['NO_INDUK']) ?></h2><p>Kelas sumber: <strong><?= la_e($student['source_class']) ?></strong> · <?= la_e($student['source_name']) ?></p><dl class="legacy-balance"><?php foreach(['SPP_PERBULAN'=>'SPP sumber','POMG'=>'Komite sumber (POMG)','DAFTAR_ULANG'=>'Daftar Ulang sumber'] as $field=>$label): ?><div><dt><?= la_e($label) ?></dt><dd><?= la_e(legacy_ui_money($sourceRaw[$field]??null)) ?></dd></div><?php endforeach; ?></dl><p>Penempatan ini menjadi awal riwayat SistemSPP. Aktivasi tidak menerbitkan tagihan atau membuat rekening Tabungan.</p><?php if($error): ?><div class="dbt-warning" role="alert"><?= la_e($error) ?></div><?php endif; ?>
<?php if($student['legacy_pending']): ?><form method="post" id="legacy-activation" class="lf-form"><noscript><p>Pilih kelas dan tahun, lalu gunakan <strong>Tampilkan Tarif</strong> sebelum mengonfirmasi aktivasi.</p></noscript><input type="hidden" name="id" value="<?= $legacyStudentId ?>"><input type="hidden" name="csrf_token" value="<?= la_e($_SESSION['csrf_legacy_activation']) ?>"><div class="dbt-import-grid"><div><label for="class-id">Kelas/rombel aktif</label><select name="class_id" id="class-id" required><option value="">Pilih rombel</option><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>" <?= $selectedClass===(int)$c['id']?'selected':'' ?>><?= la_e($c['label']) ?></option><?php endforeach; ?></select></div><div><label for="year-id">Tahun ajaran yang dikonfirmasi</label><select name="year_id" id="year-id" required><?php foreach($years as $y): ?><option value="<?= $y['id'] ?>" <?= $selectedYear===(int)$y['id']?'selected':'' ?>><?= la_e($y['label'].' · '.$y['status']) ?></option><?php endforeach; ?></select></div></div><p id="legacy-rate-status" role="status"><?= $selectedRate?'Master SPP: '.la_e($selectedRate['year']).', '.la_e(legacy_ui_money($selectedRate['net'])):'Pilih rombel untuk melihat tarif master.' ?></p><p>Komite diusulkan dari POMG sumber. Periksa nominalnya sebelum mengaktifkan siswa. SPP mengikuti master tahun dan kelas yang dipilih.</p><div class="dbt-import-grid"><?php foreach(['spp'=>'SPP sesuai master','psb'=>'PSB','komite'=>'Komite per bulan','du'=>'Daftar Ulang'] as $key=>$label): ?><div><label for="fee-<?= $key ?>"><?= $label ?> (Rp)</label><input id="fee-<?= $key ?>" name="<?= $key ?>" type="number" min="0" step="0.01" value="<?= la_e($activationValues[$key]) ?>" required <?= $key==='spp'?'readonly':'' ?>></div><?php endforeach; ?></div><label class="legacy-check-row"><input type="checkbox" name="confirmed" value="1" required> Saya mengonfirmasi tahun, rombel, dan tarif operasional ini.</label><div class="legacy-actions"><button class="btn btn-ghost" type="submit" name="action" value="preview" formnovalidate>Tampilkan Tarif</button> <button class="btn btn-primary" type="submit">Aktifkan &amp; Tempatkan</button> <a class="btn btn-ghost" href="daftar.php?status=legacy">Batal</a></div></form><?php else: ?><p>Siswa telah diaktifkan; kiriman ulang tidak membuat penempatan.</p><?php endif; ?></section></div></main></div><script id="legacy-rates" type="application/json"><?= json_encode($rates,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_HEX_APOS) ?></script><script src="../assets/js/date_format.js?v=<?= filemtime(__DIR__ . '/../assets/js/date_format.js') ?>"></script>
  <script src="../assets/js/app.js?v=<?= filemtime(__DIR__ . '/../assets/js/app.js') ?>"></script><script src="../assets/js/legacy_activation.js?v=<?= filemtime(__DIR__.'/../assets/js/legacy_activation.js') ?>"></script></body></html>
